<script setup lang="ts">
const props = defineProps<{ accountId: string; canManage: boolean }>()
const { api, path, run, loading, errors } = useAuthorizationWorkspace(() => props.accountId)
const { requestConfirmation } = useConfirmationDialog()
const view=ref('roles'),roles=ref<any[]>([]),assignments=ref<any[]>([]),catalog=ref<any[]>([]),groups=ref<any[]>([]),result=ref<any>(null),roleResult=ref<any>(null),effective=ref<any>(null),assignmentSearch=ref('')
const editDialog=ref(false),editing=ref<any>(null),roleEditDialog=ref(false),roleDeleteDialog=ref(false),editingRole=ref<any>(null)
const role=reactive<any>({name:'',description:'',permissions:[]}),roleEdit=reactive<any>({name:'',description:'',permissions:[],parent_role_ids:[]}),assignment=reactive({subject_type:'USER',user_identifier:'',subject_id:'',role_id:''}),edit=reactive({subject_type:'USER',user_identifier:'',subject_id:'',role_id:''}),check=reactive({user_identifier:'',permission:'',role_id:''})
const visibleAssignments=computed(()=>{const q=assignmentSearch.value.trim().toLowerCase();return assignments.value.filter(item=>!q||`${item.subject_name} ${item.subject_type} ${item.role_name}`.toLowerCase().includes(q))})
const permissionItems=computed(()=>catalog.value.map(item=>typeof item==='string'?item:item.id))
const parentRoleItems=computed(()=>roles.value.filter(item=>item.role_id!==editingRole.value?.role_id))
const deletingAssignments=computed(()=>assignments.value.filter(item=>item.role_id===editingRole.value?.role_id).length)
const childRoles=computed(()=>roles.value.filter(item=>item.parent_role_ids?.includes(editingRole.value?.role_id)))
function normalizedPermissions(value:any):string[]{return [...new Set((Array.isArray(value)?value:[value]).flatMap(item=>String(item||'').split(',')).map(item=>item.trim()).filter(Boolean))]}
function roleName(roleId:string){return roles.value.find(item=>item.role_id===roleId)?.name||roleId}
async function load(){const [r,a,c,g]:any[]=await Promise.all([run('roles',()=>api(path('rbac/roles'))),run('assignments',()=>api(path('rbac/assignments'))),run('catalog',()=>api(path('rbac/permissions/list'))),run('groups',()=>api(path('groups/references')))]);roles.value=r||[];assignments.value=a||[];catalog.value=c||[];groups.value=g||[]}
async function create(){const created=await run('create-role',()=>api(path('rbac/roles'),{method:'POST',body:{name:role.name,description:role.description||null,permissions:normalizedPermissions(role.permissions)}}));if(created){Object.assign(role,{name:'',description:'',permissions:[]});await load()}}
function openRoleEdit(item:any){editingRole.value=item;Object.assign(roleEdit,{name:item.name,description:item.description||'',permissions:[...item.permissions],parent_role_ids:[...item.parent_role_ids]});roleEditDialog.value=true}
function openRoleDelete(item:any){editingRole.value=item;roleDeleteDialog.value=true}
async function saveRole(){
  if(!editingRole.value)return
  const original=editingRole.value
  const nextPermissions=normalizedPermissions(roleEdit.permissions)
  const nextParents=[...new Set(roleEdit.parent_role_ids||[])].filter(id=>id!==original.role_id)
  const removedPermissions=original.permissions.filter((item:string)=>!nextPermissions.includes(item))
  const removedParents=original.parent_role_ids.filter((item:string)=>!nextParents.includes(item))
  if(removedPermissions.length||removedParents.length){
    const removals=[
      removedPermissions.length?`${removedPermissions.length} permission${removedPermissions.length===1?'':'s'}`:'',
      removedParents.length?`${removedParents.length} parent role${removedParents.length===1?'':'s'}`:'',
    ].filter(Boolean).join(' and ')
    const confirmed=await requestConfirmation({title:'Save role removals?',message:`This update removes ${removals} from ${original.name}.`,confirmText:'Save and remove'})
    if(!confirmed)return
  }
  const saved=await run('update-role',async()=>{await api(path(`rbac/roles/${original.role_id}`),{method:'PATCH',body:{name:roleEdit.name,description:roleEdit.description||null}});for(const permission of removedPermissions)await api(path(`rbac/roles/${original.role_id}/permissions`),{method:'DELETE',body:{permission}});for(const permission of nextPermissions.filter(item=>!original.permissions.includes(item)))await api(path(`rbac/roles/${original.role_id}/permissions`),{method:'POST',body:{permission}});for(const parent_role_id of removedParents)await api(path(`rbac/roles/${original.role_id}/parents`),{method:'DELETE',body:{parent_role_id}});for(const parent_role_id of nextParents.filter(item=>!original.parent_role_ids.includes(item)))await api(path(`rbac/roles/${original.role_id}/parents`),{method:'POST',body:{parent_role_id}});return true});await load();if(saved){roleEditDialog.value=false;editingRole.value=null;await refreshInspector()}}
async function deleteRole(){if(!editingRole.value)return;const deleted=await run('delete-role',async()=>{await api(path(`rbac/roles/${editingRole.value.role_id}`),{method:'DELETE'});return true});if(deleted){roleDeleteDialog.value=false;editingRole.value=null;await load();await refreshInspector()}}
async function assign(){const created=await run('assign-role',()=>api(path('rbac/assignments'),{method:'POST',body:{subject_type:assignment.subject_type,user_identifier:assignment.subject_type==='USER'?assignment.user_identifier:null,subject_id:assignment.subject_type==='GROUP'?assignment.subject_id:null,role_id:assignment.role_id}}));if(created){Object.assign(assignment,{subject_type:'USER',user_identifier:'',subject_id:'',role_id:''});await load()}}
async function refreshInspector(){if(check.user_identifier)effective.value=await run('effective',()=>api(path(`rbac/effective?user_identifier=${encodeURIComponent(check.user_identifier)}`)))}
async function unassign(item:any){const confirmed=await requestConfirmation({title:'Remove role assignment?',message:`Remove ${item.role_name} from ${item.subject_name}?`,confirmText:'Remove assignment'});if(!confirmed)return;await run(`delete-${item.assignment_id}`,()=>api(path(`rbac/assignments/${item.assignment_id}`),{method:'DELETE'}));await load();await refreshInspector()}
function openEdit(item:any){editing.value=item;Object.assign(edit,{subject_type:item.subject_type,user_identifier:item.subject_type==='USER'?item.subject_name:'',subject_id:item.subject_type==='GROUP'?item.subject_id:'',role_id:item.role_id});editDialog.value=true}
async function saveEdit(){if(!editing.value)return;const updated=await run('update-assignment',()=>api(path(`rbac/assignments/${editing.value.assignment_id}`),{method:'PATCH',body:{subject_type:edit.subject_type,user_identifier:edit.subject_type==='USER'?edit.user_identifier:null,subject_id:edit.subject_type==='GROUP'?edit.subject_id:null,role_id:edit.role_id}}));if(updated){editDialog.value=false;await load();await refreshInspector()}}
async function inspect(){result.value=null;effective.value=null;const [p,e]:any[]=await Promise.all([run('inspect',()=>api(path('rbac/check'),{method:'POST',body:{user_identifier:check.user_identifier,permission:check.permission}})),run('effective',()=>api(path(`rbac/effective?user_identifier=${encodeURIComponent(check.user_identifier)}`)))]);result.value=p;effective.value=e}
async function inspectRole(){roleResult.value=null;roleResult.value=await run('has-role',()=>api(path('rbac/has-role'),{method:'POST',body:{user_identifier:check.user_identifier,role_id:check.role_id}}))}
watch(()=>props.accountId,()=>{roles.value=[];assignments.value=[];groups.value=[];result.value=null;roleResult.value=null;effective.value=null;assignmentSearch.value='';editDialog.value=false;roleEditDialog.value=false;roleDeleteDialog.value=false;editingRole.value=null;Object.assign(role,{name:'',description:'',permissions:[]});Object.assign(check,{user_identifier:'',permission:'',role_id:''});load()},{immediate:true})
</script>
<template><div class="pa-5 pa-md-7">
    <v-alert closable v-for="(e,k) in errors" v-show="e" :key="k" type="error" variant="tonal" class="mb-3">{{e}}</v-alert><div class="d-flex align-center"><div><h2 class="text-h5">Role-based access</h2><p class="text-medium-emphasis">Typed user and group assignments with inherited permissions.</p></div><v-spacer/><v-btn icon="mdi-refresh" variant="text" :loading="loading.roles" @click="load"/></div><v-tabs v-model="view"><v-tab value="roles">Roles</v-tab><v-tab value="assignments">Assignments</v-tab><v-tab value="inspector">Access inspector</v-tab></v-tabs>
    <v-window v-model="view"><v-window-item value="roles"><v-row class="mt-2"><v-col cols="12" md="8"><v-table><thead><tr><th>Role</th><th>Own permissions</th><th>Parents</th><th v-if="canManage"/></tr></thead><tbody><tr v-for="item in roles" :key="item.role_id"><td>{{item.name}}<div v-if="item.description" class="text-caption text-medium-emphasis">{{item.description}}</div><div class="text-caption xolo-mono">{{item.role_id}}</div></td><td><v-chip v-for="p in item.permissions" :key="p" size="small" class="ma-1">{{p}}</v-chip><span v-if="!item.permissions.length">—</span></td><td><v-chip v-for="parentId in item.parent_role_ids" :key="parentId" size="small" class="ma-1" variant="tonal">{{roleName(parentId)}}</v-chip><span v-if="!item.parent_role_ids.length">—</span></td><td v-if="canManage" class="text-no-wrap"><v-btn icon="mdi-pencil-outline" variant="text" aria-label="Edit role" @click="openRoleEdit(item)"/><v-btn icon="mdi-delete-outline" variant="text" color="error" aria-label="Delete role" @click="openRoleDelete(item)"/></td></tr></tbody></v-table></v-col><v-col v-if="canManage" cols="12" md="4"><v-card variant="outlined" title="Create role"><v-card-text><v-text-field v-model="role.name" label="Name"/><v-textarea v-model="role.description" label="Description"/><v-combobox v-model="role.permissions" :items="permissionItems" multiple chips closable-chips label="Permissions" hint="Select known permissions or type a custom permission" persistent-hint/></v-card-text><v-card-actions><v-spacer/><v-btn color="primary" :loading="loading['create-role']" :disabled="!role.name.trim()" @click="create">Create</v-btn></v-card-actions></v-card></v-col></v-row></v-window-item>
    <v-window-item value="assignments"><v-card v-if="canManage" variant="outlined" class="my-4"><v-card-text><v-row><v-col cols="12" md="3"><v-select v-model="assignment.subject_type" :items="['USER','GROUP']" label="Principal type"/></v-col><v-col cols="12" md="4"><TenantUserAutocomplete v-if="assignment.subject_type==='USER'" v-model="assignment.user_identifier" :account-id="accountId"/><v-select v-else v-model="assignment.subject_id" :items="groups" item-title="name" item-value="group_id" label="Shared group"/></v-col><v-col cols="12" md="3"><v-select v-model="assignment.role_id" :items="roles" item-title="name" item-value="role_id" label="Role"/></v-col><v-col cols="12" md="2"><v-btn color="primary" block class="mt-2" @click="assign">Assign</v-btn></v-col></v-row></v-card-text></v-card><v-text-field v-model="assignmentSearch" label="Filter by username, group, role, or principal type" prepend-inner-icon="mdi-magnify"/><v-table><thead><tr><th>Principal</th><th>Role</th><th>Updated</th><th/></tr></thead><tbody><tr v-for="item in visibleAssignments" :key="item.assignment_id"><td>{{item.subject_name}} <v-chip size="x-small">{{item.subject_type}}</v-chip><div class="text-caption xolo-mono">{{item.subject_id}}</div></td><td>{{item.role_name}}</td><td>{{new Date(item.updated_at||item.assigned_at).toLocaleString()}}</td><td class="text-no-wrap"><v-btn v-if="canManage" icon="mdi-pencil-outline" variant="text" @click="openEdit(item)"/><v-btn v-if="canManage" icon="mdi-delete-outline" variant="text" color="error" @click="unassign(item)"/></td></tr></tbody></v-table></v-window-item>
    <v-window-item value="inspector">
    <v-card variant="outlined" class="mt-4">
        <v-card-text>
            <TenantUserAutocomplete v-model="check.user_identifier" :account-id="accountId" label="Tenant username"/><v-row><v-col cols="12" md="8"><v-combobox v-model="check.permission" :items="catalog.map(x=>x.id)" label="Permission"/></v-col><v-col cols="12" md="4"><v-btn block color="primary" class="mt-2" :loading="loading.inspect" @click="inspect">Check permission</v-btn></v-col><v-col cols="12" md="8"><v-select v-model="check.role_id" :items="roles" item-title="name" item-value="role_id" label="Effective role"/></v-col><v-col cols="12" md="4"><v-btn block variant="tonal" class="mt-2" :loading="loading['has-role']" @click="inspectRole">Check role</v-btn></v-col></v-row>
                
    <v-alert closable v-if="result" :type="result.has_access?'success':'error'" variant="tonal" class="mt-4">{{result.has_access?'Allowed':'Denied'}}<span v-if="result.matched_permission"> via {{result.matched_permission}}</span>
    </v-alert>
    <v-alert closable v-if="roleResult" :type="roleResult.has_role?'success':'info'" variant="tonal" class="mt-3">{{roleResult.has_role?'Role resolved':'Role not resolved'}}<div v-if="roleResult.resolution_path?.length">Path: {{roleResult.resolution_path.join(' → ')}}</div></v-alert><v-card v-if="effective" variant="tonal" class="mt-3" title="Effective details"><v-card-text><div>Direct roles: {{effective.direct_roles.join(', ')||'none'}}</div><div>Inherited roles: {{effective.inherited_roles.join(', ')||'none'}}</div><div>Own permissions: {{effective.own_permissions.join(', ')||'none'}}</div><div>Inherited permissions: {{effective.inherited_permissions.join(', ')||'none'}}</div><div v-for="(roleIds,groupId) in effective.group_roles" :key="groupId">Group {{groupId}}: {{(roleIds as string[]).join(', ')}}</div></v-card-text></v-card></v-card-text></v-card></v-window-item></v-window>

    <v-dialog v-model="roleEditDialog" max-width="720"><v-card title="Edit role"><v-card-text><v-text-field v-model="roleEdit.name" label="Name"/><v-textarea v-model="roleEdit.description" label="Description"/><v-combobox v-model="roleEdit.permissions" :items="permissionItems" multiple chips closable-chips label="Own permissions" hint="Inherited permissions come from parent roles" persistent-hint/><v-select v-model="roleEdit.parent_role_ids" :items="parentRoleItems" item-title="name" item-value="role_id" multiple chips closable-chips label="Parent roles" hint="A role inherits all permissions from its parents" persistent-hint class="mt-3"/></v-card-text><v-card-actions><v-spacer/><v-btn @click="roleEditDialog=false">Cancel</v-btn><v-btn color="primary" :loading="loading['update-role']" :disabled="!roleEdit.name.trim()" @click="saveRole">Save role</v-btn></v-card-actions></v-card></v-dialog>
    <v-dialog v-model="roleDeleteDialog" max-width="560"><v-card title="Delete RBAC role?"><v-card-text><p>This permanently deletes <strong>{{editingRole?.name}}</strong>.</p><v-alert v-if="deletingAssignments" type="warning" variant="tonal" class="mt-3">{{deletingAssignments}} assignment{{deletingAssignments===1?'':'s'}} using this role will also be deleted.</v-alert><v-alert v-if="childRoles.length" type="info" variant="tonal" class="mt-3">It will be removed as a parent from: {{childRoles.map(item=>item.name).join(', ')}}.</v-alert></v-card-text><v-card-actions><v-spacer/><v-btn @click="roleDeleteDialog=false">Cancel</v-btn><v-btn color="error" :loading="loading['delete-role']" @click="deleteRole">Delete role</v-btn></v-card-actions></v-card></v-dialog>
    <v-dialog v-model="editDialog" max-width="620"><v-card title="Edit role assignment"><v-card-text><v-select v-model="edit.subject_type" :items="['USER','GROUP']" label="Principal type"/><TenantUserAutocomplete v-if="edit.subject_type==='USER'" v-model="edit.user_identifier" :account-id="accountId"/><v-select v-else v-model="edit.subject_id" :items="groups" item-title="name" item-value="group_id" label="Shared group"/><v-select v-model="edit.role_id" :items="roles" item-title="name" item-value="role_id" label="Role"/></v-card-text><v-card-actions><v-spacer/><v-btn @click="editDialog=false">Cancel</v-btn><v-btn color="primary" :loading="loading['update-assignment']" @click="saveEdit">Save</v-btn></v-card-actions></v-card></v-dialog></div>
</template>
